            file: 'dependency.js',
            mappings: '',
            sources: ['dependency.js'],
            sourcesContent: [
                "export const value = 1;\n//# sourceMappingURL=dependency.js.map\n",
                'export const next = 2;\n/*# sourceMappingURL=next.js.map */',
